<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Hasil Bus | PURABAYA GO</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; background: #f6f3ea; color: #17211b; }
        nav { background: #071d32; color: #fff; padding: 18px 24px; display: flex; justify-content: space-between; }
        nav a { color: #fff; text-decoration: none; margin-left: 18px; }
        .wrap { max-width: 1100px; margin: 40px auto; padding: 0 16px; }
        .hero { background: #fff; border-radius: 16px; padding: 24px; box-shadow: 0 10px 25px rgba(0,0,0,.05); }
        .results-filter { background:#fff; border-radius:14px; padding:16px; margin-top:18px; display:grid; grid-template-columns:minmax(220px,1.8fr) repeat(3,minmax(125px,1fr)) auto; gap:10px; align-items:end; box-shadow:0 6px 18px rgba(0,0,0,.04); }
        .filter-field { min-width:0; } .filter-field label { display:block; margin:0 0 6px 2px; color:#607080; font-size:.72rem; font-weight:bold; }
        .results-filter input,.results-filter select { width:100%; box-sizing:border-box; padding:10px; border:1px solid #d9dde5; border-radius:8px; background:#fff; } .results-filter button { border:0; border-radius:8px; padding:10px 14px; background:#f2a62b; color:#092c45; font-weight:bold; cursor:pointer; }
        .service-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(280px,1fr)); gap:18px; margin-top:24px; }
        .service-card { background:#fff; border:1px solid #e1e8ef; border-radius:16px; padding:22px; box-shadow:0 10px 25px rgba(0,0,0,.05); transition:.2s; }
        .service-card:hover { transform:translateY(-3px); box-shadow:0 16px 30px rgba(0,0,0,.1); }
        .bus-photo { display:block; width:100%; height:auto; max-height:180px; object-fit:contain; border-radius:10px; margin-bottom:16px; } .photo-placeholder { display:grid; min-height:130px; place-items:center; margin-bottom:16px; border:1px dashed #b8ccd8; border-radius:10px; color:#607080; background:#e8f1f8; font-size:.85rem; text-align:center; } .service-card h3 { margin:0; color:#092c45; font-size:1.35rem; } .service-meta { display:flex; justify-content:space-between; align-items:center; margin:18px 0; }
        .operator-gallery { display:grid; grid-template-columns:repeat(auto-fit,minmax(110px,1fr)); gap:8px; margin-bottom:16px; }
        .operator-photo-card { overflow:hidden; border:1px solid #d9e2e8; border-radius:9px; background:#e8f1f8; }
        .operator-photo-card img { display:block; width:100%; height:auto; max-height:120px; object-fit:contain; background:#f3f7fa; }
        .operator-photo-empty { display:grid; width:100%; height:82px; place-items:center; color:#607080; font-size:.7rem; text-align:center; }
        .operator-photo-name { display:block; overflow:hidden; padding:6px; color:#092c45; font-size:.72rem; font-weight:bold; text-overflow:ellipsis; white-space:nowrap; }
        .badge { display:inline-block; padding:7px 11px; border-radius:999px; font-weight:bold; font-size:.82rem; } .patas { background:#fff0d1; color:#9b5c00; } .ekonomi { background:#e1f1ff; color:#126394; } .executive { background:#eee5ff; color:#6942a1; }
        .shelter { color:#4e6977; font-weight:bold; } .operators { color:#284d5e; line-height:1.65; min-height:52px; } .fare { border-top:1px solid #e8edf0; padding-top:15px; margin-top:18px; display:flex; justify-content:space-between; gap:10px; color:#607080; } .fare strong { color:#d47f0c; }
        .schedule-list { color:#284d5e; line-height:1.7; margin:8px 0 0; } .schedule-status { display:inline-block; margin-top:12px; font-size:.8rem; font-weight:bold; } .status-available { color:#218739; } .status-estimated { color:#a06a00; } .status-flexible { color:#6f7880; } .schedule-note { color:#687d87; font-size:.85rem; margin:4px 0 0; } .btn { display:block; text-align:center; margin-top:18px; padding:10px 12px; background:#0d6efd; color:#fff; text-decoration:none; border-radius:8px; font-weight:bold; } @media(max-width:1050px){.results-filter{grid-template-columns:repeat(3,1fr)}} @media(max-width:600px){.results-filter{grid-template-columns:1fr}}
    </style>
</head>
<body>
    <nav><strong>PURABAYA GO</strong><div><a href="<?= site_url('/') ?>">Home</a><a href="<?= site_url('search') ?>">Cari Bus</a><a href="<?= site_url('guide') ?>">Guide</a><a href="<?= site_url('about') ?>">About</a><?php if (session()->get('logged_in')): ?><a href="<?= site_url(session()->get('role') === 'admin' ? 'admin/dashboard' : 'user/dashboard') ?>">Dashboard</a><a href="<?= site_url('logout') ?>">Logout</a><?php else: ?><a href="<?= site_url('login') ?>">Login</a><?php endif; ?></div></nav>
    <div class="wrap">
        <div class="hero"><h2><?= esc($destination['destination_name'] ?? 'Hasil pencarian bus') ?><?php if (!empty($busClass)): ?> - <?= esc(ucfirst($busClass)) ?><?php endif; ?></h2><p><?= count($buses) ?> pilihan layanan dari Terminal Purabaya</p></div>
        <form class="results-filter" action="<?= site_url('search') ?>" method="get" aria-label="Filter hasil bus"><div class="filter-field"><label for="search-query">Cari bus atau tujuan</label><input id="search-query" name="q" value="<?= esc($filters['q'] ?? '') ?>" placeholder="Nama bus atau kota"></div><div class="filter-field"><label for="search-category">Kelas</label><select id="search-category" name="category"><option value="">Semua kelas</option><?php foreach (['ekonomi' => 'Ekonomi', 'patas' => 'Patas', 'executive' => 'Eksekutif'] as $value => $label): ?><option value="<?= $value ?>" <?= ($filters['category'] ?? '') === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="search-destination">Tujuan</label><select id="search-destination" name="destination_id"><option value="">Semua tujuan</option><?php foreach (($destinations ?? []) as $item): ?><option value="<?= esc($item['id']) ?>" <?= (string) ($filters['destination_id'] ?? '') === (string) $item['id'] ? 'selected' : '' ?>><?= esc($item['destination_name']) ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="search-fare">Tarif maksimal</label><input id="search-fare" name="fare" type="number" min="0" value="<?= esc($filters['fare'] ?? '') ?>" placeholder="Rp"></div><button type="submit">Cari</button></form>
        <?php if (empty($buses)): ?><p>Bus tidak ditemukan.</p><?php else: ?><div class="service-grid">
        <?php foreach ($buses as $bus): ?><?php $schedule = $bus['schedules'][0] ?? []; $operatorServices = $bus['operator_services'] ?? []; $statusLabels = ['available' => 'Jadwal tersedia', 'estimated' => 'Perkiraan jadwal', 'flexible' => 'Operasional fleksibel']; ?><article class="service-card"><?php if (count($operatorServices) > 1): ?><div class="operator-gallery" aria-label="Foto bus setiap operator"><?php foreach ($operatorServices as $service): ?><div class="operator-photo-card"><?php if (!empty($service['photo'])): ?><img src="<?= base_url('uploads/bus/' . rawurlencode($service['photo'])) ?>" alt="<?= esc($service['photo_alt'] ?? 'Foto bus ' . $service['operator']) ?>"><?php else: ?><div class="operator-photo-empty">Foto belum tersedia</div><?php endif; ?><span class="operator-photo-name"><?= esc($service['operator']) ?></span></div><?php endforeach; ?></div><?php elseif (!empty($bus['photo'])): ?><img class="bus-photo" src="<?= base_url('uploads/bus/' . rawurlencode($bus['photo'])) ?>" alt="<?= esc($bus['photo_alt'] ?? 'Foto bus') ?>"><?php else: ?><div class="photo-placeholder" role="status">Foto bus belum tersedia</div><?php endif; ?><h3><?= esc($bus['destination_name']) ?></h3><div class="service-meta"><span class="badge <?= esc($bus['bus_class']) ?>"><?= esc(ucfirst($bus['bus_class'])) ?></span><span class="shelter">&#128205; Shelter <?= esc($bus['shelter_number']) ?></span></div><strong>&#128652; <?= esc(implode(', ', $bus['operators'])) ?></strong><div class="fare"><span>&#128176; Tarif</span><strong>Rp<?= number_format($bus['fare_min'], 0, ',', '.') ?><?= $bus['fare_max'] > $bus['fare_min'] ? ' - Rp' . number_format($bus['fare_max'], 0, ',', '.') : '' ?></strong></div><strong>&#128336; Keberangkatan</strong><p class="schedule-list"><?php $timeValues = array_filter(array_map(static fn (array $item): ?string => $item['departure_time'] ? substr($item['departure_time'], 0, 5) : null, $bus['schedules'])); ?><?= esc($timeValues ? implode(' · ', $timeValues) : 'Lihat catatan operasional') ?></p><span class="schedule-status status-<?= esc($schedule['schedule_status'] ?? 'estimated') ?>">&#9679; <?= esc($statusLabels[$schedule['schedule_status'] ?? 'estimated']) ?></span><?php if (!empty($schedule['frequency']) || !empty($schedule['note'])): ?><p class="schedule-note"><?= esc(trim(($schedule['frequency'] ?? '') . (($schedule['frequency'] ?? '') && ($schedule['note'] ?? '') ? ' · ' : '') . ($schedule['note'] ?? ''))) ?></p><?php endif; ?><a class="btn" href="<?= site_url('bus/' . $bus['id']) ?>">Lihat Detail &rarr;</a></article><?php endforeach; ?></div><?php endif; ?>
    </div>
</body>
</html>
